<template>
 <div class="info-backdrop automatic-training-backdrop" @mousedown.self="$emit('close')" @keydown.stop @keyup.stop>
  <section ref="panel" class="automatic-training" role="dialog" aria-modal="true" aria-labelledby="automatic-training-title" tabindex="-1" @keydown.esc.prevent="$emit('close')" data-automatic-training>
   <header><span class="training-symbol" aria-hidden="true">↻</span><div><small>ENTRAÎNEMENT</small><h2 id="automatic-training-title">{{ isIv?'Relances d’IV':'Relances de nature' }}</h2></div><button class="training-close" aria-label="Fermer" @click="$emit('close')">×</button></header>
   <div class="training-content">
    <p>Choisis ton objectif. Les relances s’arrêtent dès qu’il est atteint ou lorsque le stock est épuisé. Tu peux les interrompre à tout moment.</p>
    <div class="training-fields"><label>Pokémon<select v-model="pokemonUuid" :disabled="running||busy" data-auto-pokemon><option value="">Choisir un Pokémon…</option><option v-for="p in team" :key="p.uuid" :value="p.uuid" :disabled="p.isEgg||p.currentHp<=0">{{ p.name }} · Niv. {{ p.level }}</option></select></label>
    <label v-if="isIv">Statistique<select v-model="stat" :disabled="running||busy" data-auto-stat><option v-for="s in stats" :key="s.key" :value="s.key">{{ s.label }} ({{ stockFor(s.key) }})</option></select></label>
    <label v-if="isIv">IV à atteindre<select v-model.number="targetIv" :disabled="running||busy" data-auto-target><option v-for="n in 32" :key="n" :value="n-1">{{ n-1 }} / 31</option></select></label>
    <label v-else>Nature souhaitée<select v-model="targetNature" :disabled="running||busy" data-auto-target><option v-for="n in natureChoices" :key="n.key" :value="n.key">{{ n.label }} · {{ n.effect }}</option></select></label></div>
    <article v-if="pokemon" class="training-target"><pokemon-portrait :src="$pokemonSprite(pokemon)" :alt="pokemon.name"/><div><b>{{ pokemon.name }}</b><span>{{ isIv?statLabel+' : '+current+' / 31':natureName(current) }}</span><small>{{ isIv?'Objectif : '+targetIv+' / 31':'Objectif : '+natureName(targetNature) }}</small></div><strong>×{{ stock }}</strong></article>
    <div v-if="job" class="training-progress" role="status" aria-live="polite" :class="{'is-complete':job.phase==='complete'}"><b>{{ status }}</b><div role="progressbar" aria-label="Part du stock utilisé" :aria-valuenow="job.used" :aria-valuemax="Math.max(1,job.stock||0)" aria-valuemin="0"><i :style="{width:depletion+'%'}"/></div><span>{{ job.used }} objet{{ job.used>1?'s':'' }} utilisé{{ job.used>1?'s':'' }} · {{ job.remaining ?? stock }} restant{{ (job.remaining ?? stock)>1?'s':'' }}</span><p v-if="job.message">{{ job.message }}</p></div>
    <p v-if="error" class="training-error" role="alert">{{ error }}</p>
    <p class="training-hint">La dernière valeur obtenue est conservée, même si elle est plus basse. Chaque utilisation est sauvegardée ; seuls les objets réellement utilisés sont consommés.</p>
   </div>
   <footer><button @click="$emit('close')">{{ running?'Arrêter et fermer':'Fermer' }}</button><button v-if="running" class="training-primary" :disabled="busy" data-auto-stop @click="$emit('stop')">{{ busy?'Arrêt en cours…':'Arrêter les relances' }}</button><button v-else class="training-primary" :disabled="busy||!pokemon||pokemon.isEgg||pokemon.currentHp<=0||stock<=0&&!alreadyReached" data-auto-start @click="$emit('start',{kind:isIv?'iv':'nature',pokemonUuid,stat,target:isIv?targetIv:targetNature})">{{ busy?'Un instant…':alreadyReached?'Vérifier l’objectif':'Démarrer' }}</button></footer>
  </section>
 </div>
</template>
<script>
import PokemonPortrait from '../PokemonPortrait.vue';
import {natures,natureLabel,natureDescription} from '@/services/pokemonNatures';
const stats=[{key:'hp',label:'PV'},{key:'attack',label:'Attaque'},{key:'defense',label:'Défense'},{key:'specialAttack',label:'Attaque Spéciale'},{key:'specialDefense',label:'Défense Spéciale'},{key:'speed',label:'Vitesse'}];
export default{components:{PokemonPortrait},props:{team:Array,items:Array,initial:Object,job:Object,busy:Boolean,error:String},data(){return{pokemonUuid:this.initial.pokemonUuid||'',stat:this.initial.stat||'hp',targetIv:31,targetNature:'Modest',stats};},computed:{
 isIv(){return this.initial.kind==='iv';},running(){return this.job?.phase==='running';},pokemon(){return this.team.find(p=>p.uuid===this.pokemonUuid);},statLabel(){return stats.find(s=>s.key===this.stat)?.label;},
 item(){return this.items.find(i=>this.isIv?i.fieldUse?.ivReroll===this.stat:i.fieldUse?.natureReroll);},stock(){return this.item?.quantity||0;},current(){return this.isIv?this.pokemon?.iv?.[this.stat]:this.pokemon?.nature;},alreadyReached(){return this.isIv?this.current===this.targetIv:this.current===this.targetNature;},
 natureChoices(){return Object.keys(natures).map(key=>({key,label:natureLabel(key),effect:natureDescription(key)})).sort((a,b)=>a.label.localeCompare(b.label,'fr'));},
 status(){return{running:'Relances en cours…',complete:'Objectif atteint !',exhausted:'Stock épuisé',cancelled:'Relances arrêtées',error:'Relances interrompues'}[this.job?.phase]||'';},depletion(){return Math.min(100,100*(this.job?.used||0)/Math.max(1,this.job?.stock||0));}
 },mounted(){this._previous=document.activeElement;this.$refs.panel.focus({preventScroll:true});this._trap=e=>{if(e.key!=='Tab')return;const a=[...this.$refs.panel.querySelectorAll('button:not(:disabled),select:not(:disabled)')],first=a[0],last=a.at(-1);if(e.shiftKey&&[first,this.$refs.panel].includes(document.activeElement)){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}};this.$refs.panel.addEventListener('keydown',this._trap);},beforeDestroy(){this.$refs.panel?.removeEventListener('keydown',this._trap);if(this._previous?.isConnected)this._previous.focus({preventScroll:true});},methods:{natureName:natureLabel,stockFor(stat){return this.items.find(i=>i.fieldUse?.ivReroll===stat)?.quantity||0;}}};
</script>
<style scoped>
.automatic-training{width:min(620px,100%);max-height:calc(100dvh - 30px);display:flex;flex-direction:column;overflow:hidden;color:var(--journal-ink);background:var(--journal-paper);border:1px solid var(--journal-border);border-radius:14px;box-shadow:var(--journal-shadow);font:13px/1.5 var(--journal-font);text-align:left}.automatic-training *{box-sizing:border-box}.automatic-training header{display:flex;align-items:center;gap:12px;padding:18px 22px;background:var(--journal-soft);border-bottom:1px solid var(--journal-border)}header>div{flex:1}header small{font-size:8px;letter-spacing:.12em;color:var(--journal-muted)}h2{font:24px Georgia,serif;color:var(--journal-heading);margin:3px 0 0}.training-symbol{font-size:30px;color:var(--journal-accent)}button,select{font:inherit;color:inherit;min-height:42px;border:1px solid var(--journal-border);border-radius:7px;background:var(--journal-card);padding:8px 11px}button{cursor:pointer}button:disabled{opacity:.55;cursor:default}.training-close{border-radius:50%;font-size:23px;width:40px;padding:0}.training-content{overflow:auto;padding:5px 22px 18px;overscroll-behavior:contain}.training-content>p{font-size:12px}.training-fields{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin:17px 0}.training-fields label{display:flex;flex-direction:column;gap:6px;font-size:11px;font-weight:600;min-width:0}.training-fields label:first-child{grid-column:1/-1}.training-fields select{min-width:0;width:100%;font-size:12px}.training-target{display:flex;align-items:center;gap:12px;padding:12px;background:var(--journal-card);border:1px solid var(--journal-border);border-radius:9px}.training-target .pokemon-portrait{width:60px;height:65px;object-fit:contain;image-rendering:pixelated}.training-target>div{flex:1;min-width:0}.training-target b,.training-target span,.training-target small{display:block}.training-target span{color:var(--journal-accent);margin-top:4px}.training-target small{font-size:10px;color:var(--journal-muted)}.training-target>strong{font-variant-numeric:tabular-nums;font-size:17px}.training-progress{margin-top:18px;padding:12px;border:1px solid var(--journal-border);border-radius:8px;background:var(--journal-soft)}.training-progress>b{color:var(--journal-heading)}.training-progress>div{height:7px;background:var(--journal-border);border-radius:5px;overflow:hidden;margin:10px 0 5px}.training-progress i{display:block;height:100%;background:var(--journal-accent);transition:width .15s}.training-progress>span{font-size:11px;color:var(--journal-muted)}.training-progress.is-complete{border-color:#74a68b}.training-progress p,.training-error{font-size:12px;color:var(--journal-danger)}.training-hint{color:var(--journal-muted);font-size:10px!important;line-height:1.6;margin:16px 0 0}.automatic-training footer{display:flex;gap:10px;justify-content:flex-end;padding:14px 22px;border-top:1px solid var(--journal-border)}.training-primary{background:var(--journal-accent);color:var(--journal-on-accent);border-color:var(--journal-accent)}button:focus-visible,select:focus-visible{outline:2px solid var(--journal-accent);outline-offset:2px}@media(max-width:500px){.automatic-training{border-radius:11px;max-height:calc(100dvh - 16px)}.automatic-training header{padding:14px}.training-content{padding:4px 14px 14px}.automatic-training footer{padding:12px 14px}h2{font-size:21px}.training-fields{gap:10px}.training-target .pokemon-portrait{width:47px;height:54px}.automatic-training footer button{font-size:12px}}@media(prefers-reduced-motion:reduce){.training-progress i{transition:none}}
header,footer{flex:none}
</style>
